'use strict';
const siteContent=JSON.parse(document.getElementById('site-content')?.textContent||'null');
const htmlEscape=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const inventory = siteContent?.inventory || [
 {id:'sup',name:'САПборды',label:'САПборд',quantity:45,price:1000,unit:'час',image:'sup.webp',description:'Свобода, баланс и ваш собственный темп.',position:'50% 70%'},
 {id:'catamaran',name:'Электрокатамараны',label:'Электрокатамаран',quantity:3,price:5000,unit:'час',image:'catamaran.webp',description:'Устроиться поудобнее и отправиться по воде.',position:'50% 46%'},
 {id:'boat',name:'Катер без капитана',label:'Катер без капитана',quantity:1,price:10000,unit:'час',image:'harbor.webp',description:'Прогулка по большой акватории.',position:'95% 75%'},
 {id:'captain',name:'Катер с капитаном',label:'Катер с капитаном',quantity:1,price:15000,unit:'час',image:'boat.webp',description:'Ваш отдых — маршрут доверяем капитану.',position:'50% 50%'},
 {id:'kayak',name:'Каяк одноместный',label:'Каяк одноместный',quantity:1,price:1000,unit:'час'},
 {id:'kayak2',name:'Каяк двухместный',label:'Каяк двухместный',quantity:1,price:1000,unit:'час'},
 {id:'kayak3',name:'Каяк трёхместный',label:'Каяк трёхместный',quantity:1,price:1000,unit:'час'},
 {id:'big',name:'Big SUP',label:'Big SUP',quantity:1,price:1000,unit:'человек / час'},
 {id:'electric',name:'ЭлектроСАП',label:'ЭлектроСАП',quantity:2,price:1500,unit:'час'},
 {id:'bike',name:'ВелоСАП',label:'ВелоСАП',quantity:2,price:1000,unit:'час'},
 {id:'rowing',name:'Вёсельные лодки',label:'Вёсельная лодка',quantity:2,price:1000,unit:'час'},
];
const money = value => new Intl.NumberFormat('ru-RU').format(value) + ' ₽';
const $ = selector => document.querySelector(selector);
$('#fleet-grid').innerHTML = inventory.slice(0,4).map(item => `<article class="fleet-card"><a class="fleet-photo photo-open" href="${htmlEscape(item.imageFull||item.image)}" aria-label="Открыть фото: ${htmlEscape(item.name)}"><img src="${item.image.startsWith('/')?item.image:'assets/'+item.image}" alt="${htmlEscape(item.name)} на станции СТАРТ" ${item.imageSrcSet?`srcset="${item.imageSrcSet}" sizes="(max-width: 580px) 45vw, (max-width: 850px) 50vw, 25vw"`:""} decoding="async" loading="lazy" width="600" height="450" style="object-position:${item.position}"></a><div class="fleet-content"><h3>${htmlEscape(item.name)}</h3><p>${htmlEscape(item.description)} В парке: ${item.quantity} шт.</p>${item.id==='sup'?'<p>Гидрокостюм — бесплатно.</p>':''}<div class="fleet-bottom"><span class="fleet-price">${item.price ? money(item.price) + ' <small>/ час</small>' : 'Уточнить цену'}</span><button class="round-button" data-equipment="${item.id}" aria-label="Выбрать: ${htmlEscape(item.name)}">↗</button></div></div></article>`).join('');
$('#extra-fleet').innerHTML = inventory.slice(4).map(item => `<article class="extra-item">${item.image?`<a class="extra-photo photo-open" href="${htmlEscape(item.imageFull||item.image)}" aria-label="Открыть фото: ${htmlEscape(item.name)}"><img src="${htmlEscape(item.image)}" ${item.imageSrcSet?`srcset="${item.imageSrcSet}" sizes="88px"`:""} loading="lazy" decoding="async" width="88" height="88" alt="${htmlEscape(item.name)}"></a>`:""}<div><h3>${htmlEscape(item.name)}</h3><p>${item.price ? money(item.price) + ' / ' + item.unit : 'Стоимость уточнит сотрудник'}${item.quantity ? ' · В парке: '+item.quantity+' шт.' : ''}</p></div><button class="round-button" data-equipment="${item.id}" aria-label="Выбрать: ${htmlEscape(item.name)}">↗</button></article>`).join('');
$('#equipment').innerHTML = inventory.map(i=>`<option value="${i.id}">${htmlEscape(i.label)}</option>`).join('');
const minute=t=>Number(t.slice(0,2))*60+Number(t.slice(3));const opening=minute(siteContent?.open||'09:00'),closing=minute(siteContent?.close||'22:00');
const times=Array.from({length:Math.max(1,(closing-opening)/30)},(_,i)=>{const m=opening+i*30;return String(Math.floor(m/60)).padStart(2,'0')+':'+String(m%60).padStart(2,'0');});
for (const id of ['time','quick-time']) $('#'+id).innerHTML=times.map(t=>`<option value="${t}">${t}</option>`).join('');
function moscowToday(){const p=new Intl.DateTimeFormat('en-CA',{timeZone:'Europe/Moscow',year:'numeric',month:'2-digit',day:'2-digit'}).formatToParts(new Date());return `${p.find(x=>x.type==='year').value}-${p.find(x=>x.type==='month').value}-${p.find(x=>x.type==='day').value}`;}
const today=moscowToday();
function nextSeasonDate(date){const year=Number(date.slice(0,4));const md=date.slice(5);if(md<'04-01')return `${year}-04-01`;if(md>'11-01')return `${year+1}-04-01`;return date;}
for(const id of ['quick-date','date','return-date']){$('#'+id).min=today;$('#'+id).value=nextSeasonDate(today);}
const dialog=$('#booking-dialog');
function showBooking(equipment='sup',plan='hour'){$('#equipment').value=equipment;$('#plan').value=plan;$('#booking-form').hidden=false;$('#booking-result').hidden=true;$('#copy-status').textContent='';updateForm();dialog.showModal();window.startAnalytics?.goal('booking_open');document.body.classList.add('dialog-open');}
document.querySelectorAll('[data-book]').forEach(b=>b.addEventListener('click',()=>showBooking()));
document.querySelectorAll('[data-equipment]').forEach(b=>b.addEventListener('click',()=>showBooking(b.dataset.equipment)));
document.querySelectorAll('[data-plan]').forEach(b=>b.addEventListener('click',()=>showBooking('sup',b.dataset.plan)));
$('.close-dialog').addEventListener('click',()=>dialog.close());dialog.addEventListener('close',()=>document.body.classList.remove('dialog-open'));
dialog.addEventListener('click',event=>{if(event.target===dialog){const r=dialog.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)dialog.close();}});
$('#menu-toggle').addEventListener('click',()=>{const open=$('#navigation').classList.toggle('open');$('#menu-toggle').setAttribute('aria-expanded',String(open));$('#menu-toggle').setAttribute('aria-label',open?'Закрыть меню':'Открыть меню');});
document.querySelectorAll('#navigation a').forEach(a=>a.addEventListener('click',()=>{$('#navigation').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}));
function validSeason(date){return Boolean(date)&&date>=moscowToday()&&date.slice(5)>='04-01'&&date.slice(5)<='11-01';}
$('#quick-book').addEventListener('submit',event=>{event.preventDefault();const date=$('#quick-date');date.setCustomValidity(validSeason(date.value)?'':'Выберите дату сезона: с 1 апреля по 1 ноября, не ранее сегодняшнего дня.');if(!date.reportValidity())return;$('#date').value=date.value;$('#time').value=$('#quick-time').value;showBooking($('#quick-equipment').value);});
$('#quick-date').addEventListener('input',()=>$('#quick-date').setCustomValidity(''));
const routes={sup:{text:'Короткая прогулочная петля от станции с возвращением в Ореховую бухту.'},catamaran:{text:'Большая петля по акватории с возвращением к причалу «СТАРТ».'},boat:{text:'Вытянутая петля по акватории со стартом и возвращением на станцию.'}};
let currentRoute='sup';
function selectRoute(id){if(!routes[id])return false;currentRoute=id;document.querySelectorAll('[data-route]').forEach(b=>{const active=b.dataset.route===id;b.classList.toggle('active',active);b.setAttribute('aria-pressed',String(active));});document.querySelectorAll('[data-map-route]').forEach(p=>p.classList.toggle('active',p.dataset.mapRoute===id));$('#route-description').textContent=routes[id].text;$('#book-route').textContent='Выбрать водное развлечение ↗';return true;}
document.querySelectorAll('[data-route]').forEach(b=>b.addEventListener('click',()=>selectRoute(b.dataset.route)));
const map=$('#water-map');map.setAttribute('role','group');
map.querySelectorAll('path[data-map-route]').forEach(path=>{const id=path.dataset.mapRoute;const hit=path.cloneNode(false);hit.removeAttribute('data-map-route');hit.setAttribute('class','route-hit');hit.dataset.route=id;hit.setAttribute('role','button');hit.setAttribute('tabindex','0');hit.setAttribute('aria-label','Маршрут: '+({sup:'САПборд',catamaran:'Электрокатамаран',boat:'Катер без капитана'})[id]);hit.setAttribute('aria-pressed',String(id===currentRoute));hit.addEventListener('click',()=>selectRoute(id));hit.addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectRoute(id);}});map.append(hit);});
$('#book-route').addEventListener('click',()=>showBooking(currentRoute));
function selectedItem(){return inventory.find(i=>i.id===$('#equipment').value);}
function updateForm(){const p=$('#plan').value;const special=p!=='hour';if(special)$('#equipment').value='sup';$('#equipment').disabled=special;$('#return-field').hidden=p!=='takeaway';$('#return-date').required=p==='takeaway';$('#return-date').min=$('#date').value;$('#duration-field').hidden=special;$('#quantity-field').hidden=p==='season';$('.time-field').hidden=p==='season';$('.date-field').hidden=p==='season';$('#date').required=p!=='season';$('#duration').disabled=special;$('#time').disabled=p==='season';$('#quantity').disabled=p==='season';let estimate='';const quantity=p==='season'?1:Number($('#quantity').value);if(p==='season')estimate=money(siteContent?.plans.season??20000)+' за именной сезонный абонемент';else if(p==='day')estimate=money((siteContent?.plans.day??5000)*quantity)+' за день';else if(p==='takeaway')estimate=money((siteContent?.plans.takeaway??5000)*quantity)+' за день + залог '+money(siteContent?.plans.deposit??5000)+' за САП. Срок аренды согласует сотрудник.';else{const i=selectedItem();estimate=i.price?money(i.price*Number($('#duration').value)*quantity)+' за '+$('#duration').selectedOptions[0].textContent.toLowerCase():'Стоимость уточнит сотрудник';}$('#quantity-field').firstChild.textContent=selectedItem()?.id==='big'?'Количество человек':'Количество';$('#estimate').textContent=estimate;}
for(const id of ['equipment','plan','date','return-date','duration','quantity'])$('#'+id).addEventListener('input',()=>{$('#date').setCustomValidity('');$('#return-date').setCustomValidity('');$('#time').setCustomValidity('');updateForm();});
$('#time').addEventListener('change',()=>$('#time').setCustomValidity(''));
$('#booking-form').addEventListener('submit',async event=>{event.preventDefault();if(siteContent?.preview){$('#estimate').textContent='Предпросмотр: отправка заявки отключена.';return;}const p=$('#plan').value;const date=$('#date');const time=$('#time');date.setCustomValidity(p==='season'||validSeason(date.value)?'':'Выберите дату сезона с 1 апреля по 1 ноября.');const h=Number(time.value.slice(0,2))+Number(time.value.slice(3))/60;time.setCustomValidity(p==='hour'&&h*60+Number($('#duration').value)*60>closing?'Прогулка должна завершиться до закрытия. Выберите более раннее время.':'');const returnDate=$('#return-date');returnDate.setCustomValidity(p==='takeaway'&&(!validSeason(returnDate.value)||returnDate.value<date.value||returnDate.value.slice(0,4)!==date.value.slice(0,4))?'Выберите дату возврата в этом сезоне, не раньше даты выдачи.':'');const phone=$('[name="phone"]');phone.setCustomValidity(phone.value.replace(/\D/g,'').length<10?'Укажите телефон полностью.':'');if(!event.target.reportValidity())return;if(window.startTelegram?.enabled){await window.startTelegram.send();return;}const data=new FormData(event.target);const lines=['Здравствуйте! Хочу оформить заявку в СТАРТ.',`Техника: ${selectedItem().label}`,`Тариф: ${$('#plan').selectedOptions[0].textContent}`];if(p!=='season')lines.push(`Дата: ${date.value.split('-').reverse().join('.')}`,`Время: ${time.value} (Москва)`);if(p==='hour')lines.push(`Длительность: ${$('#duration').selectedOptions[0].textContent}`);if(p==='takeaway')lines.push(`Возврат: ${returnDate.value.split('-').reverse().join('.')}`);lines.push(`Количество${selectedItem().id==='big'?' человек':''}: ${p==='season'?1:$('#quantity').value}`,`Стоимость: ${$('#estimate').textContent}`,`Имя: ${String(data.get('name')).trim()}`,`Телефон: ${data.get('phone')}`,'Прошу подтвердить наличие и условия.');$('#message-preview').value=lines.join('\n');$('#booking-form').hidden=true;$('#booking-result').hidden=false;$('#copy-message').focus();});
$('[name="phone"]').addEventListener('input',event=>event.target.setCustomValidity(''));
$('#copy-message').addEventListener('click',async()=>{try{await navigator.clipboard.writeText($('#message-preview').value);$('#copy-status').textContent='Скопировано. Теперь вставьте заявку в чат с сотрудником.';}catch{$('#message-preview').focus();$('#message-preview').select();$('#copy-status').textContent='Выделили текст — скопируйте его вручную.';}});
$('#back-to-form').addEventListener('click',()=>{$('#booking-result').hidden=true;$('#booking-form').hidden=false;});
// Optional WebMCP surface: reading prices and selecting a route never creates a booking.
if(document.modelContext?.registerTool){
  const lifecycle=new AbortController();
  const definitions=[
    {name:'read_start_rental_options',description:'Read published rental prices and booking mode. Null price means staff must quote it.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute:()=>({inventory:inventory.map(({id,label,price,unit,quantity})=>({id,label,price,unit,quantity})),bookingMode:window.startTelegram?.enabled?'Submit a request to staff via the server. Staff confirmation is required; no reservation is created.':'Prepare text, then manually send to staff in Telegram; no reservation is created.'})},
    {name:'select_start_route',description:'Display a one-hour suggested route on the homepage map. Does not reserve equipment.',inputSchema:{type:'object',properties:{route:{type:'string',enum:['sup','catamaran','boat']}},required:['route'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute:input=>{if(!input||typeof input!=='object'||!Object.hasOwn(routes,input.route))throw new Error('Unknown route');selectRoute(input.route);return {route:currentRoute,description:routes[currentRoute].text,approximateMinutes:60};}}
  ];
  for(const definition of definitions){try{Promise.resolve(document.modelContext.registerTool(definition,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
  window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}

const requestedEquipment=new URLSearchParams(location.search).get("equipment");if([...document.querySelector("#equipment").options].some(o=>o.value===requestedEquipment))showBooking(requestedEquipment);
